from ta5g_global_var import DEFAULT_ENB_ALIAS
from ta5g_interface_tools import ta5g_interface_tools
from .syslog_messages import SyslogMessages


class syslog_analyzer:
    """
    Interface for syslog analysis methods.
    """

    def __init__(self, syslog_lib):
        self.syslog_messages = SyslogMessages(syslog_lib)

    def verify_syslog_for_given_number_of_messages(
        self, regexp, number_of_messages, alias=DEFAULT_ENB_ALIAS, logs_dirpath=None, remote_host='127.0.0.1'
    ):
        """
        Counts the occurrences of message in syslog file and compare with expected number
        (number should be equal to expected number).
        :param string regexp: Pattern used to find the message in the syslog file.
        :param integer number_of_messages: Number of messages to compare.
        :param string alias: Unique identifier for a certain syslog instance.
        :param string logs_dirpath: Path to directory where syslog file should be stored.
        :param string remote_host: Ip address of eNB host PC.
        """
        fixed_alias = ta5g_interface_tools.add_remote_host_suffix(alias=alias, remote_host=remote_host)
        number_of_messages = int(number_of_messages)
        self.syslog_messages.verify_syslog_for_given_number_of_messages(
            regexp=regexp,
            number_of_messages=number_of_messages,
            alias=fixed_alias,
            log_dir=logs_dirpath,
            compare_operator='==',
        )

    def verify_syslog_for_no_messages(
        self, regexp, alias=DEFAULT_ENB_ALIAS, logs_dirpath=None, remote_host='127.0.0.1'
    ):
        """
        Counts the occurrences of message in syslog file and compare with 0 (number should be equal to 0).
        :param string regexp: Pattern used to find the message in the syslog file.
        :param string alias: Unique identifier for a certain syslog instance.
        :param string logs_dirpath: Path to directory where syslog file should be stored.
        :param string remote_host: Ip address of eNB host PC.
        """
        fixed_alias = ta5g_interface_tools.add_remote_host_suffix(alias=alias, remote_host=remote_host)
        self.syslog_messages.verify_syslog_for_given_number_of_messages(
            regexp=regexp, number_of_messages=0, alias=fixed_alias, log_dir=logs_dirpath, compare_operator='=='
        )

    def verify_syslog_for_at_least_given_number_of_messages(
        self, regexp, number_of_messages, alias=DEFAULT_ENB_ALIAS, logs_dirpath=None, remote_host='127.0.0.1'
    ):
        """
        Counts the occurrences of message in syslog file and compare with expected number
        (should be greater than nor equal to expected number).
        :param string regexp: Pattern used to find the message in the syslog file.
        :param integer number_of_messages: Number of messages to compare.
        :param string alias: Unique identifier for a certain syslog instance.
        :param string logs_dirpath: Path to directory where syslog file should be stored.
        :param string remote_host: Ip address of eNB host PC.
        """
        fixed_alias = ta5g_interface_tools.add_remote_host_suffix(alias=alias, remote_host=remote_host)
        number_of_messages = int(number_of_messages)
        self.syslog_messages.verify_syslog_for_given_number_of_messages(
            regexp=regexp,
            number_of_messages=number_of_messages,
            alias=fixed_alias,
            log_dir=logs_dirpath,
            compare_operator='>=',
        )

    def wait_for_specified_message_in_syslog(
        self, msg_regexp, alias=DEFAULT_ENB_ALIAS, timeout=10, remote_host='127.0.0.1'
    ):
        """
        Waits for a message to appear in the syslog file.
        :param string msg_regexp: Pattern used to find the message in the syslog file.
        :param string alias: Unique identifier for a certain syslog instance.
        :param string timeout: Maximum time to wait for the message in seconds.
        :param string remote_host: Ip address of eNB host PC.
        """
        fixed_alias = ta5g_interface_tools.add_remote_host_suffix(alias=alias, remote_host=remote_host)
        self.syslog_messages.syslog_lib.wait_for_message_in_syslog_file(
            regexp=msg_regexp, alias=fixed_alias, timeout=timeout
        )
